<?php
declare(strict_types=1);
function page_breadcrumb(string $parent,string $label): void { ?><nav class="breadcrumbs" aria-label="İçerik yolu"><a href="/">Ana sayfa</a><span aria-hidden="true">/</span><a href="<?=e($parent)?>"><?=e($label)?></a></nav><?php }
function varied_opening(string $view,array $data,array $s,array $extra): void {
 $d=page_design($view);$image=(int)($d['image_id']??0);if(!$image&&!empty($d['cover']))$image=studio_cover($d['cover']);
 if($view==='services'): ?>
 <section class="capabilities-opening opening-<?=e($d['layout'])?>"><div class="capabilities-title"><?php page_breadcrumb('/hizmetler','Hizmetler'); ?><span class="studio-eyebrow">ARKESOFT / UZMANLIK ALANLARI</span><h1><?=e($d['title'])?></h1><p><?=e($d['intro'])?></p></div><div class="capabilities-index"><?php foreach(cms_records('categories') as $i=>$c): ?><a href="#expertise-<?=$c['id']?>"><small><?=sprintf('%02d',$i+1)?></small><strong><?=e($c['name'])?></strong><span aria-hidden="true">↓</span></a><?php endforeach; ?></div><?php if($d['layout']==='cards'): ?><div class="capability-previews"><?php foreach(cms_records('categories') as $i=>$c): ?><a href="/uzmanlik/<?=e($c['slug'])?>"><?=media_image($image&&$i===0?$image:studio_cover(['flow','coffee','architecture'][$i%3]))?><span><?=e($c['name'])?> ↗</span></a><?php endforeach; ?></div><?php endif; ?></section>
 <?php elseif($view==='category'):$c=$data['category'];$type=(int)$c['id']===2?'brand':((int)$c['id']===3?'growth':'software'); ?>
 <section class="category-opening category-<?=$type?>"><div><?php page_breadcrumb('/hizmetler','Hizmetler'); ?><span class="studio-eyebrow">UZMANLIK ALANI / <?=sprintf('%02d',(int)$c['sort_order'])?></span><h1><?=e($c['name'])?></h1><p><?=e($c['description'])?></p><a class="outline-pill" href="/iletisim">İhtiyacınızı konuşalım ↗</a></div><figure><?=media_image(studio_cover(match($type){'brand'=>'coffee','growth'=>'architecture',default=>'flow'}),'',true)?><figcaption>ARKESOFT / KONSEPT SEÇKİSİ</figcaption></figure></section>
 <?php elseif($view==='service'):$service=$data['service'];$layout=service_layout($service,$extra);$image=(int)($extra['image_id']??0); ?>
 <section class="service-opening service-layout-<?=e($layout)?>" data-service-layout="<?=e($layout)?>"><div class="service-opening-copy"><?php page_breadcrumb('/hizmetler','Hizmetler'); ?><span class="studio-eyebrow"><?=e($service['eyebrow'])?></span><h1><?=e($service['name'])?></h1><p><?=e($service['summary'])?></p><a class="studio-button" href="/iletisim">Birlikte planlayalım ↗</a><?php if(in_array($layout,['software','growth'],true)): ?><ol class="service-opening-points"><?php foreach(array_slice(lines($service['deliverables']),0,3) as $line): ?><li><?=e($line)?></li><?php endforeach; ?></ol><?php endif; ?></div><div class="service-opening-stage"><?php if($layout==='web'): ?><div class="browser-chrome" aria-hidden="true"><span>● ● ●</span><span>ARKESOFT / WEB DENEYİMİ</span></div><?php endif; ?><?=media_image($image,'',true)?><?php if($layout==='mobile'): ?><span class="mobile-stage-note">KÜÇÜK EKRAN.<br>BÜYÜK BİR FİKİR.</span><?php elseif($layout==='brand'): ?><div class="brand-stage-caption"><span>Bir karakter.</span><span>Her temas noktasında.</span></div><?php elseif($layout==='commerce'): ?><div class="commerce-stage-caption"><span>Keşfet</span><span>Seç</span><span>Sipariş ver ↗</span></div><?php elseif($layout==='software'): ?><div class="software-stage-caption"><span>İHTİYAÇ</span><b aria-hidden="true">→</b><span>AKIŞ</span><b aria-hidden="true">→</b><span>ÇALIŞAN ÜRÜN</span></div><?php elseif($layout==='growth'): ?><span class="growth-stage-caption" aria-hidden="true">Doğru<br>yerde.<br>Doğru<br>sözle.</span><?php endif; ?></div></section>
 <?php elseif($view==='projects'): ?>
 <section class="portfolio-opening"><div><?php page_breadcrumb('/projeler','Projeler'); ?><span class="studio-eyebrow">ARKESOFT / SEÇİLİ KONSEPTLER</span><h1><?=e($d['title'])?></h1></div><p><?=e($d['intro'])?></p><span class="portfolio-arrow" aria-hidden="true">↙</span></section>
 <?php elseif($view==='project'):$p=$data['project'];$layout=($extra['project_layout']??'auto')!=='auto'?$extra['project_layout']:match($p['style']){'morrow'=>'product','orbit'=>'product-ui',default=>'editorial'}; ?>
 <section class="case-opening case-layout-<?=e($layout)?>"><div class="case-opening-title"><?php page_breadcrumb('/projeler','Projeler'); ?><span class="studio-eyebrow"><?=e($p['category'])?><?=$p['is_demo']?' / KONSEPT ÇALIŞMA':''?></span><h1><?=e($p['name'])?></h1><p><?=e($p['description'])?></p></div><figure><?=media_image((int)($extra['image_id']??0),'',true)?><figcaption><?=e($p['name'])?> / <?=e($p['category'])?></figcaption></figure></section>
 <?php elseif($view==='about'): ?>
 <section class="manifesto-opening manifesto-<?=e($d['layout'])?>"><div class="manifesto-title"><?php page_breadcrumb('/hakkimizda','Hakkımızda'); ?><span class="studio-eyebrow">MERAK / EMEK / İLETİŞİM</span><h1><?=e($d['title'])?></h1></div><figure><?=media_image($image,'',true)?><figcaption>ARKESOFT / KONSEPT STÜDYO GÖRSELİ</figcaption></figure><div class="manifesto-note"><span aria-hidden="true">a↗</span><p><?=e($d['intro'])?></p></div></section>
 <?php elseif($view==='contact'): ?>
 <section class="contact-opening"><?php page_breadcrumb('/iletisim','İletişim'); ?><div><h1><?=e($d['title'])?></h1><p><?=e($d['intro'])?></p></div></section>
 <?php elseif($view==='blog'):$articles=published_articles();$featured=$articles[0]??null; ?>
 <section class="journal-opening"><div><span class="studio-eyebrow">ARKESOFT / İÇGÖRÜLER</span><h1><?=e($d['title'])?></h1><p><?=e($d['intro'])?></p></div><span class="journal-edition">NOTLAR & REHBERLER<br><?=date('Y')?></span></section><?php if($featured&&$d['layout']==='magazine'): ?><section class="journal-feature"><a class="journal-feature-image" href="/blog/<?=e($featured['slug'])?>" aria-label="<?=e($featured['title'])?>"><?=media_image((int)($d['image_id']?:$featured['image_id']),'',true)?></a><div><span class="studio-eyebrow">ÖNE ÇIKAN YAZI / <?=e($featured['category'])?></span><h2><a href="/blog/<?=e($featured['slug'])?>"><?=e($featured['title'])?></a></h2><p><?=e($featured['excerpt'])?></p><a class="outline-pill" href="/blog/<?=e($featured['slug'])?>">Yazıyı okuyun ↗</a></div></section><?php endif; ?>
 <?php elseif($view==='article'):$a=$data['article']; ?>
 <section class="essay-opening"><?php page_breadcrumb('/blog','İçgörüler'); ?><span class="studio-eyebrow"><?=e($a['category'])?></span><h1><?=e($a['title'])?></h1><p><?=e($a['excerpt'])?></p><span class="essay-author"><?=e($a['author'])?> · <?=e(date('d.m.Y',strtotime($a['published_at'])))?></span></section><?php if($a['image_id']): ?><figure class="essay-cover"><?=media_image((int)$a['image_id'],'',true)?></figure><?php endif; ?>
 <?php elseif($view==='landing'):$p=$data['page'];$svc=record('services',(int)$p['service_id']);$city=record('cities',(int)$p['city_id']); ?>
 <section class="local-opening"><div><?php page_breadcrumb('/cozumler','Yerel çözümler'); ?><span class="studio-eyebrow"><?=e($city['name']??'TÜRKİYE')?> / ÇALIŞMA KAPSAMI</span><h1><?=e($p['heading'])?></h1><p><?=e($p['intro'])?></p></div><aside><span class="local-pin" aria-hidden="true">↗</span><h2><?=e($city['name']??'Türkiye')?></h2><p><?=e($svc['name']??'Dijital çözümler')?></p><span>Çevrim içi proje görüşmesi</span><a href="/iletisim" class="studio-button">Kapsamı konuşalım ↗</a></aside></section>
 <?php elseif($view==='solutions'): ?>
 <section class="directory-opening"><div><?php page_breadcrumb('/cozumler','Yerel çözümler'); ?><span class="studio-eyebrow">HİZMET × LOKASYON</span><h1><?=e($d['title'])?></h1><p><?=e($d['intro'])?></p></div><div class="directory-scope"><strong>81</strong><span>İL İÇİN ÇEVRİM İÇİ<br>PROJE GÖRÜŞMESİ</span><a href="#local-directory">Çözümleri inceleyin ↓</a></div></section>
 <?php elseif($view==='privacy'): ?>
 <section class="document-opening"><?php page_breadcrumb('/gizlilik','Gizlilik'); ?><span class="studio-eyebrow">BİLGİLENDİRME</span><h1><?=e($d['title'])?></h1><p><?=e($d['intro'])?></p></section>
 <?php else: ?>
 <section class="missing-opening"><span aria-hidden="true">404</span><div><span class="studio-eyebrow">BİR YOL AYRIMI</span><h1><?=e($d['title']??'Bu sayfa bulunamadı.')?></h1><p><?=e($d['intro']??'Ana sayfadan devam edebilirsiniz.')?></p></div></section>
 <?php endif;
}
